"""
    Given local, target and outlier density (as estimated by KNN) calculate
    the probability of retaining the event. If local density is less than or
    equal to the outlier density, returns a probability of 0 (event will be
    discarded). If the local density is greater than the outlier density
    but less than the target density, return a value of 1 (absolutely keep this
    event). If the local density is greater than the target density, then
    the probability of retention is the ratio between the target and local
    density.

    Parameters
    ----------
    local_d: int
    target_d: int
    outlier_d: int

    Returns
    -------
    float
        Value between 0 and 1
    """
def prob_downsample(local_d: int, target_d: int, outlier_d: int) -> object {
    if (local_d <= outlier_d) {
        return 0;
    }
    if (outlier_d < local_d <= target_d) {
        return 1;
    }
    if (local_d > target_d) {
        return (target_d / local_d);
    }
}

"""
    This converts a WMI type name to the equivalent XSD type, as a string.
    Later, the conversion to a 'real' XSD type is straightforward.
    The point of this conversion is that it does not need rdflib.

    WMI types: https://powershell.one/wmi/datatypes
    RDF types: https://rdflib.readthedocs.io/en/stable/rdf_terms.html
    """
def _convert_wmi_type_to_xsd_type(predicate_type_name: Any) -> object {
    wmi_type_to_xsd = {
        'string': "survol_string",
        'boolean': 'survol_boolean',
        'datetime': 'survol_dateTime',
        'sint64': 'survol_integer',
        'sint32': 'survol_integer',
        'sint16': 'survol_integer',
        'sint8': 'survol_integer',
        'uint64': 'survol_integer',
        'uint32': 'survol_integer',
        'uint16': 'survol_integer',
        'uint8': 'survol_integer',
        'real64': 'survol_double',
        'real32': 'survol_double'
    };
    try {
        return wmi_type_to_xsd[predicate_type_name.lower()];
    } except KeyError {
        return None;
    }
}

"""Join multiple list of path segments

    This function is not encoding aware, it does not test for, or changed the
    encoding of the path segments it's passed.

    Example::
        >>> assert join_path_segments(['a'], ['b']) == ['a','b']
        >>> assert join_path_segments(['a',''], ['b']) == ['a','b']
        >>> assert join_path_segments(['a'], ['','b']) == ['a','b']
        >>> assert join_path_segments(['a',''], ['','b']) == ['a','','b']
        >>> assert join_path_segments(['a','b'], ['c','d']) == ['a','b','c','d']

    :param args: optional  arguments
    :return: :class:`list`, the segment list of the result path
    """
def join_path_segments(*args: Any) -> object {
    finals = [];
    for segments in args {
        if (not segments or (segments[0] == [''])) {
            continue;
        } elif not finals {
            finals.extend(segments);
        } else {
            if ((finals[-1] == '') and ((segments[0] != '') or (len(segments) > 1))) {
                finals.pop(-1);
            } elif (
                (finals[-1] != '') and (segments[0] == '') and (len(segments) > 1)
            ) {
                segments.pop(0);
            }
            finals.extend(segments);
        }
    }
    return finals;
}

"""
    :param iter: Iterable collection of sets
    :return: The union of all of the sets
    """
def BigUnion(iter: Any) -> object {
    union = `set();
    for s in iter {
        union.update(s);
    }
    return union;
}
